<?php $this->layout('default'); use Moves\Services\CmsVersions as C; use Moves\Support\CmsView as V; $product = V::queryString('produto'); if (!isset(C::PRODUCTS[$product])) { $product = 'cms'; } $current = C::current(); $rows = C::listing($product); $name = C::PRODUCTS[$product][0];
$this->start('actions'); ?><span class="cms-online"><?= V::e($name) ?> atual: <?= V::e($current[$product] ?? 'sem versão') ?></span><?php $this->stop(); ?>
<nav class="cms-products" aria-label="Produtos"><?php foreach (C::PRODUCTS as $key => [$label, $icon]): ?><a class="cms-product<?= $key === $product ? ' selected' : '' ?>" href="?produto=<?= V::e($key) ?>"<?= $key === $product ? ' aria-current="true"' : '' ?>><?= V::icon($icon) ?><span><strong><?= V::e($label) ?></strong><small><?= isset($current[$key]) ? 'v' . V::e($current[$key]) : 'Sem versão' ?></small></span></a><?php endforeach; ?></nav>
<div class="cms-form-list"><form class="cms-card" method="post" action="/acao/version-publish"><header class="cms-card-head"><div><h2>Publicar versão</h2><small>Altera somente o histórico deste produto.</small></div><?= V::icon('tag') ?></header><?= V::csrf() ?><input type="hidden" name="product" value="<?= V::e($product) ?>"><div class="cms-form-grid"><?= V::field('Número da versão *', 'version', '', ['required' => true, 'help' => 'Ex.: 1.1.0']) ?><?= V::field('Nome da entrega', 'name') ?></div><?= V::field('Notas da versão *', 'notes', '', ['type' => 'textarea', 'rows' => 6, 'required' => true]) ?><button class="cms-btn-primary" style="width:100%">Publicar versão de <?= V::e($name) ?></button></form>
<section class="cms-card"><header class="cms-card-head"><h2>Versões publicadas</h2><b class="cms-count"><?= count($rows) ?></b></header><?php if ($rows === []): ?><?= V::empty('Nenhuma versão publicada.') ?><?php endif; foreach ($rows as $i => $v): ?><article class="cms-timeline-item"><i><?= V::icon('check') ?></i><div><strong>v<?= V::e($v['version']) ?><?= $v['name'] !== '' ? ' · ' . V::e($v['name']) : '' ?></strong> <?= $i === 0 ? V::badge('active', 'Atual') : '' ?><p><?= V::e($v['notes']) ?></p><small><?= V::date($v['created_at']) ?> · <?= V::e($v['author'] ?? 'Sistema') ?></small></div></article><?php endforeach; ?></section></div>
